import { Navigate, Outlet } from 'react-router-dom'
import { useAuth } from '@/app/providers/AuthProvider'

// Bootstrap fallback: emails listed here get admin access even before the
// user_roles table is seeded. Remove once roles are managed in Supabase.
const BOOTSTRAP_ADMIN_EMAILS: string[] = ['admin@xcamp.co', 'shared@xchange.eco', 'fabian+260602@xchange.eco', 'dev-superadmin@xcamp.local']

export function AdminGuard() {
  const { user, isAdmin, isLoading } = useAuth()

  if (isLoading) return null

  const allowed = !!user && (isAdmin || BOOTSTRAP_ADMIN_EMAILS.includes(user.email))

  if (!allowed) {
    return <Navigate to="/app/home" replace />
  }

  return <Outlet />
}
